class Solution:
    def sumOfGoodNumbers(self, nums: List[int], k: int) -> int:
        n = len(nums)
        total_sum = 0
        for i in range(n):
            # Check left neighbor if it exists
            if i - k >= 0:
                if nums[i] > nums[i - k]:
                    continue  # continue to right neighbor
            # Check right neighbor if it exists
            if i + k < n:
                if nums[i] > nums[i + k]:
                    continue  # continue to right neighbor
            # If both neighbors are checked and one is greater, it's good
            if i - k >= 0 and i + k < n:
                if nums[i] > nums[i - k]:
                    total_sum += nums[i]
        return total_sum
