class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        graph = [[] for _ in range(n)]

        # Build the graph
        for i in range(n):
            for j in range(n):
                if i == j:
                    continue
                # Calculate intersection size
                common = set(properties[i]) & set(properties[j])
                if len(common) >= k:
                    graph[i].append(j)
                    graph[j].append(i)

        # Count connected components
        visited = [False] * n
        components = 0

        for i in range(n):
            if not visited[i]:
                components += 1
                stack = [i]
                while stack:
                    node = stack.pop()
                    for neighbor in graph[node]:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            stack.append(neighbor)

        return components
